create table if not exists public.cbt_exam_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,exam text not null,subject text not null,mode text not null check(mode in('practice','simulation')),question_ids uuid[] not null,option_maps jsonb not null default '{}'::jsonb,started_at timestamptz not null default now(),expires_at timestamptz not null,submitted_at timestamptz,score integer,total integer not null,status text not null default 'active' check(status in('active','submitted','expired')),unique(id,user_id));
alter table public.cbt_exam_sessions add column if not exists option_maps jsonb not null default '{}'::jsonb;alter table public.cbt_exam_sessions add column if not exists expires_at timestamptz;alter table public.cbt_exam_sessions enable row level security;drop policy if exists "cbt sessions own read" on public.cbt_exam_sessions;create policy "cbt sessions own read" on public.cbt_exam_sessions for select using(auth.uid()=user_id);
create or replace function public.start_verified_cbt_session(p_exam text,p_subject text,p_mode text,p_count integer,p_duration_minutes integer) returns table(session_id uuid,question_id uuid,topic text,question_text text,options jsonb,position integer,expires_at timestamptz) language plpgsql security definer set search_path=public as $$
declare sid uuid;ids uuid[];maps jsonb:='{}'::jsonb;expiry timestamptz;qid uuid;perm int[];shuffled jsonb;
begin if auth.uid() is null then raise exception 'authentication required';end if;if length(trim(coalesce(p_exam,'')))<1 or length(trim(coalesce(p_subject,'')))<1 then raise exception 'exam and subject required';end if;if p_mode not in('practice','simulation') or p_count<1 or p_count>60 or p_duration_minutes<1 or p_duration_minutes>180 then raise exception 'invalid session request';end if;
 with pool as(select q.id,q.topic,coalesce(h.times_seen,0) seen,case when p_mode='practice' then coalesce(h.times_correct::numeric/nullif(h.times_seen,0),1) else 1 end mastery from public.cbt_verified_questions q left join public.cbt_question_history h on h.user_id=auth.uid() and h.exam=p_exam and h.subject=p_subject and h.question_id=q.id::text where q.active=true and q.exam=trim(p_exam) and q.subject=trim(p_subject)),ranked as(select *,row_number() over(partition by topic order by(seen=0)desc,mastery asc,random()) topic_rank from pool),chosen as(select id from ranked order by(seen=0)desc,topic_rank asc,mastery asc,random() limit p_count) select array_agg(id) into ids from chosen;if coalesce(array_length(ids,1),0)<>p_count then raise exception 'verified bank not ready';end if;
 foreach qid in array ids loop select array_agg(i order by random()) into perm from generate_series(0,3)i;maps:=maps||jsonb_build_object(qid::text,to_jsonb(perm));end loop;expiry:=now()+make_interval(mins=>p_duration_minutes);insert into public.cbt_exam_sessions(user_id,exam,subject,mode,question_ids,option_maps,total,expires_at)values(auth.uid(),trim(p_exam),trim(p_subject),p_mode,ids,maps,p_count,expiry)returning id into sid;
 return query select sid,q.id,q.topic,q.question_text,(select jsonb_agg(q.options->p.idx order by p.ord) from jsonb_array_elements_text(maps->q.id::text) with ordinality ptxt(v,ord) cross join lateral(select ptxt.v::int idx)p),u.ord::integer,expiry from unnest(ids)with ordinality u(id,ord)join public.cbt_verified_questions q on q.id=u.id order by u.ord;end;$$;
create or replace function public.submit_verified_cbt_session(p_session_id uuid,p_answers jsonb) returns table(score integer,total integer,unanswered integer,timed_out boolean) language plpgsql security definer set search_path=public as $$ declare s public.cbt_exam_sessions;earned integer:=0;missing integer:=0;q public.cbt_verified_questions;display_answer integer;original_index integer;expired boolean;begin if auth.uid() is null then raise exception 'authentication required';end if;if p_answers is null or jsonb_typeof(p_answers)<>'object' then raise exception 'answers must be an object';end if;select * into s from public.cbt_exam_sessions where id=p_session_id and user_id=auth.uid() for update;if not found then raise exception 'session not found';end if;if s.status<>'active' then raise exception 'session already closed';end if;expired:=s.expires_at is not null and now()>s.expires_at;foreach q in array(select array_agg(v)from public.cbt_verified_questions v where v.id=any(s.question_ids))loop if p_answers?q.id::text and jsonb_typeof(p_answers->q.id::text)='number' and(p_answers->q.id::text)::text~'^[0-3]$' then display_answer:=((p_answers->q.id::text)::text)::int;original_index:=((s.option_maps->q.id::text)->>display_answer)::int;if original_index=q.correct_option then earned:=earned+1;end if;else missing:=missing+1;end if;end loop;update public.cbt_exam_sessions set score=earned,submitted_at=now(),status=case when expired then'expired'else'submitted'end where id=s.id;return query select earned,s.total,missing,expired;end;$$;
revoke all on function public.start_verified_cbt_session(text,text,text,integer,integer)from public;revoke all on function public.submit_verified_cbt_session(uuid,jsonb)from public;grant execute on function public.start_verified_cbt_session(text,text,text,integer,integer)to authenticated;grant execute on function public.submit_verified_cbt_session(uuid,jsonb)to authenticated;
